// =====================================================================
//  ⚙️  CONFIGURAÇÃO DO ALERTA DE OFERTAS — você só precisa editar ESTE nó
// =====================================================================
const CONFIG = {
  // --- Evolution API (v2) ---
  evolutionUrl: 'https://SUA-EVOLUTION-API.com.br', // sem "/" no final
  instancia: 'NOME_DA_SUA_INSTANCIA',

  // --- Para onde vão os alertas ---
  // Seu número com DDI + DDD, só dígitos. Também aceita o ID de um grupo (ex.: '1203...@g.us').
  meuNumero: '5511999999999',

  // --- Grupos de WhatsApp monitorados ---
  // Formato: 'ID_DO_GRUPO@g.us': 'Nome que aparece no alerta'
  // Não sabe o ID? Mande a mensagem  !id  dentro do grupo (pelo seu número)
  // que o workflow te responde no privado com o ID.
  grupos: {
    // '120363000000000000@g.us': 'Ofertas de TVs',
  },

  // --- Canais PÚBLICOS do Telegram (opcional) ---
  // Canais do WhatsApp NÃO chegam pela Evolution; muitos têm espelho no Telegram.
  // Só funciona se abrir no navegador: https://t.me/s/<usuario>
  canaisTelegram: [
    // { usuario: 'achadosdotb', nome: 'Achados do Tecnoblog' },
    // { usuario: 'ofertasadrenaline', nome: 'Ofertas Adrenaline' },
  ],

  // --- IA (opcional, recomendado) ---
  // true  = o pré-filtro seleciona e a IA confirma (menos alarme falso, permite preço máximo)
  // false = só o pré-filtro por palavras decide (grátis)
  usarIA: true,
  modeloIA: 'gpt-5-mini',

  // Não repete o mesmo texto de oferta dentro desse intervalo
  dedupHoras: 12,

  // =====================================================================
  //  ALERTAS — um bloco por tipo de produto. Copie um bloco para criar outro.
  //
  //  precisaTer : lista de listas. A mensagem precisa ter PELO MENOS UM termo
  //               de CADA lista. Ex.: [['oled'], ['lg','samsung']] = "oled" E ("lg" OU "samsung")
  //  naoPodeTer : se aparecer qualquer um desses termos, descarta
  //  Termos ignoram maiúsculas e acentos e casam palavra inteira ('55' não casa com 'R$ 1.559').
  //  Para regex, comece com 're:'  (ex.: 're:oled(55|65)' casa com 'OLED55C4')
  //  criterio   : descrição em português que a IA usa para confirmar
  //  precoMaximo: número em reais (ex.: 4500) ou null. Só funciona com usarIA = true
  //  grupos     : [] = todas as fontes; ou nomes específicos (os mesmos de "grupos"/"canaisTelegram")
  // =====================================================================
  alertas: [
    {
      nome: 'TV OLED LG/Samsung 55" ou 65"',
      ativo: true,
      precisaTer: [
        ['oled', 're:oled\\d{2}', 're:qn\\d{2}s9'],
        ['lg', 'samsung', 're:oled\\d{2}[a-z]', 're:qn\\d{2}s9'],
        ['55', '65', 're:oled(55|65)', 're:qn(55|65)'],
      ],
      naoPodeTer: ['suporte', 'capa', 'controle remoto', 'soundbar'],
      criterio:
        'Oferta de Smart TV com tecnologia OLED (inclui QD-OLED) da marca LG ou Samsung, com tela de ' +
        'exatamente 55 ou 65 polegadas. NÃO vale: QLED, Neo QLED, NanoCell, QNED, Mini-LED, LED comum, ' +
        'outras marcas, outros tamanhos, acessórios ou mensagens que não são oferta.',
      precoMaximo: null,
      grupos: [],
    },
    {
      nome: 'iPhone 16 / 16 Pro até R$ 5.000',
      ativo: false, // exemplo — mude para true para usar
      precisaTer: [['iphone'], ['16']],
      naoPodeTer: ['capinha', 'capa', 'pelicula', 'carregador', 'cabo'],
      criterio:
        'Oferta de um iPhone 16, 16 Plus, 16 Pro ou 16 Pro Max NOVO (não recondicionado, não seminovo). ' +
        'NÃO vale: acessórios, outros modelos de iPhone.',
      precoMaximo: 5000,
      grupos: [],
    },
  ],
};
return [{ json: CONFIG }];

// Normaliza a mensagem que chegou da Evolution e decide se ela interessa
const cfg = $('CONFIG').first().json;
const body = $('WhatsApp (Evolution)').first().json.body || {};
const d = body.data || {};
const jid = d.key?.remoteJid || '';
const m = d.message || {};
const texto =
  m.conversation || m.extendedTextMessage?.text || m.imageMessage?.caption || m.videoMessage?.caption || '';

// Comando "!id": responde no privado com o ID do grupo/chat onde foi enviado
if (d.key?.fromMe && texto.trim().toLowerCase() === '!id') {
  return [{ json: { mensagemPronta:
    `🆔 ID deste chat:\n${jid}\n\nCole no nó CONFIG, em "grupos":\n'${jid}': 'Nome do grupo',` } }];
}
if (body.event && body.event !== 'messages.upsert') return [];
if (d.key?.fromMe || !cfg.grupos[jid] || !texto.trim()) return [];
return [{ json: { fonte: cfg.grupos[jid], texto } }];

// Lê a prévia pública (t.me/s/<canal>) e emite só os posts novos desde a última execução
const store = $getWorkflowStaticData('global');
store.ultimoPost = store.ultimoPost || {};
const canais = $('Lista canais do Telegram').all();
const limpa = (s) => s
  .replace(/<br\s*\/?>/g, '\n').replace(/<[^>]+>/g, '')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(+n))
  .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
  .trim();
const out = [];
$input.all().forEach((it, i) => {
  const c = canais[i].json;
  const html = it.json.data;
  if (typeof html !== 'string') return;
  const posts = [];
  for (const b of html.split('tgme_widget_message_wrap').slice(1)) {
    const id = +((b.match(/data-post="[^"\/]+\/(\d+)"/) || [])[1] || 0);
    const m = b.match(/<div class="tgme_widget_message_text[^"]*"[^>]*>([\s\S]*?)<\/div>/);
    if (id && m) posts.push({ id, texto: limpa(m[1]) });
  }
  if (!posts.length) return;
  const ultimo = store.ultimoPost[c.usuario];
  store.ultimoPost[c.usuario] = Math.max(ultimo || 0, ...posts.map((p) => p.id));
  if (ultimo === undefined) return; // 1ª execução: só marca a posição, não manda o histórico
  for (const p of posts) if (p.id > ultimo) out.push({ json: { fonte: c.nome || c.usuario, texto: p.texto } });
});
return out;

// Aplica os ALERTAS do CONFIG: pré-filtro por palavras + dedup + prepara a pergunta pra IA
const cfg = $('CONFIG').first().json;
const store = $getWorkflowStaticData('global');
store.vistos = store.vistos || {};
const agora = Date.now();
for (const [k, ts] of Object.entries(store.vistos)) {
  if (agora - ts > (cfg.dedupHoras || 12) * 3600e3) delete store.vistos[k];
}

const norm = (s) => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const regex = (t) => t.startsWith('re:')
  ? new RegExp(t.slice(3), 'i')
  : new RegExp('(^|[^a-z0-9])' + norm(t).replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '(?=$|[^a-z0-9])', 'i');
const tem = (txt, termo) => regex(termo).test(txt);

const PROMPT =
  'Você classifica mensagens de grupos de ofertas. Responda SOMENTE um JSON no formato ' +
  '{"match": boolean, "produto": string, "preco": string, "preco_numero": number|null, "motivo": string}. ' +
  'match=true apenas se a mensagem for uma oferta que atende EXATAMENTE ao critério. ' +
  'produto = nome curto (marca, modelo, variação). preco = menor preço anunciado como texto (ex.: "R$ 4.299 no Pix"). ' +
  'preco_numero = esse preço em reais como número (ex.: 4299.9), ou null se não houver.';

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.mensagemPronta) { out.push({ json: j }); continue; } // ex.: resposta do !id
  const txt = norm(j.texto || '');
  for (const a of cfg.alertas || []) {
    if (!a.ativo) continue;
    if (a.grupos?.length && !a.grupos.includes(j.fonte)) continue;
    if (!(a.precisaTer || []).every((lista) => lista.some((t) => tem(txt, t)))) continue;
    if ((a.naoPodeTer || []).some((t) => tem(txt, t))) continue;
    const chave = a.nome + '|' + txt.replace(/\s+/g, ' ').trim().slice(0, 300);
    if (store.vistos[chave]) continue;
    store.vistos[chave] = agora;
    out.push({ json: {
      alerta: a.nome,
      fonte: j.fonte,
      texto: j.texto,
      precoMaximo: a.precoMaximo ?? null,
      usarIA: !!cfg.usarIA,
      payload: {
        model: cfg.modeloIA,
        response_format: { type: 'json_object' },
        messages: [
          { role: 'system', content: PROMPT },
          { role: 'user', content: `CRITÉRIO: ${a.criterio}\n\nMENSAGEM:\n${j.texto}` },
        ],
      },
    } });
  }
}
return out;

// Junta a resposta da IA com a oferta e descarta o que não bateu (ou passou do preço máximo)
const out = [];
$input.all().forEach((it, i) => {
  const src = $('Usar IA?').itemMatching(i).json;
  let r = null;
  try { r = JSON.parse(it.json.choices[0].message.content); } catch (e) {}
  if (r && r.match === false) return;
  if (r && src.precoMaximo && typeof r.preco_numero === 'number' && r.preco_numero > src.precoMaximo) return;
  // Se a IA falhar (sem crédito, fora do ar...), avisa mesmo assim marcando "não verificado"
  out.push({ json: { ...src, produto: r?.produto || '', preco: r?.preco || '', verificado: !!r } });
});
return out;

// Monta o texto final do alerta
const cfg = $('CONFIG').first().json;
return $input.all().map(({ json: s }) => {
  if (s.mensagemPronta) return { json: { numero: cfg.meuNumero, texto: s.mensagemPronta } };
  const cabecalho = [
    `🔔 *${s.alerta}*${s.usarIA && !s.verificado ? ' _(não verificado pela IA)_' : ''}`,
    `📍 ${s.fonte}`,
    s.produto ? `🏷️ ${s.produto}${s.preco ? ' — *' + s.preco + '*' : ''}` : null,
  ].filter(Boolean).join('\n');
  return { json: { numero: cfg.meuNumero, texto: `${cabecalho}\n\n${s.texto}` } };
});
